  assert.deepEqual(replay.job.output, oldOutput); for (const [name, bytes] of beforeReplay) assert.deepEqual(root.files.get(name), bytes);
  const next = createJob(root, corrected, "corrected-colour-request", at(6));
  assert.equal(next.replayed, false); assert.notEqual(next.job.jobId, historicalJob.jobId); assert.equal(next.job.specDigest, corrected.specDigest);
  assert.equal(next.job.targetAssetId, historicalJob.targetAssetId); assert.equal(next.job.targetVersion, 2); assert.equal(next.job.output, null);
  assert.deepEqual(next.ledger.outputs, [oldOutput]); assert.deepEqual(next.ledger.jobs[0], replay.job); assert.deepEqual(root.files.get(oldSpecEntry[0]), oldBytes);
